package com.yonlab.vision;
import android.content.Context;import android.graphics.Bitmap;import java.io.*;import java.util.*;
/** YuNet2026 dynamic re-export; same detector weights, explicit stride-head decode. */
final class OneYuNet implements AutoCloseable {
 private final OneOnnx model;OneYuNet(Context c)throws Exception{model=new OneOnnx(c,"yunet-2026-sface");}
 synchronized List<float[]> detect(Bitmap image)throws Exception{return model.run(image,result->{List<float[]> candidates=new ArrayList<>();for(int stride:new int[]{8,16,32}){float[][] cls=((float[][][])OneOnnx.value(result,"cls_"+stride))[0],obj=((float[][][])OneOnnx.value(result,"obj_"+stride))[0],box=((float[][][])OneOnnx.value(result,"bbox_"+stride))[0],kps=((float[][][])OneOnnx.value(result,"kps_"+stride))[0];int cols=640/stride,n=cols*cols;if(cls.length!=n||obj.length!=n||box.length!=n||kps.length!=n)throw new IOException("YuNet output anchors");for(int i=0;i<n;i++){if(cls[i].length!=1||obj[i].length!=1||box[i].length!=4||kps[i].length!=10)throw new IOException("YuNet output width");float score=(float)Math.sqrt(OneModelMath.clip(cls[i][0])*OneModelMath.clip(obj[i][0]));if(!OneModelMath.finite(score)||score<.8f)continue;float[] b=box[i];float w=(float)Math.exp(b[2])*stride,h=(float)Math.exp(b[3])*stride,cx=(i%cols+b[0])*stride,cy=(i/cols+b[1])*stride;float[] row=new float[15];row[0]=cx-w/2;row[1]=cy-h/2;row[2]=w;row[3]=h;row[14]=score;for(int j=0;j<10;j+=2){row[4+j]=(i%cols+kps[i][j])*stride;row[5+j]=(i/cols+kps[i][j+1])*stride;}boolean valid=true;for(float f:row)valid&=OneModelMath.finite(f);if(valid&&w>0&&h>0)candidates.add(row);}}candidates.sort((a,b)->Float.compare(b[14],a[14]));List<float[]> kept=new ArrayList<>();for(float[] row:candidates){boolean overlaps=false;for(float[] other:kept)if(iou(row,other)>.3f){overlaps=true;break;}if(!overlaps)kept.add(row);if(kept.size()>=200)break;}return kept;});}
 private static float iou(float[] a,float[] b){float w=Math.max(0,Math.min(a[0]+a[2],b[0]+b[2])-Math.max(a[0],b[0])),h=Math.max(0,Math.min(a[1]+a[3],b[1]+b[3])-Math.max(a[1],b[1]));float area=w*h;return area/(a[2]*a[3]+b[2]*b[3]-area);}
 public void close(){model.close();}
}
